Ошибка Код Retry? Действие Throttling <code>Throttling</code>, <code>ThrottlingException</code>, <code>RequestLimitExceeded</code> да, с backoff adaptive retry 5xx <code>InternalError</code>, <code>ServiceUnavailable</code> да backoff 429 <code>TooManyRequestsException</code> да jittered backoff 4xx <code>NoSuchBucket</code>, <code>AccessDenied</code>, <code>ValidationError</code> нет исправить запрос Timeout <code>ReadTimeoutError</code>, <code>ConnectTimeoutError</code> да увеличить timeout <pre><code>import time
import random
from botocore.exceptions import ClientError, BotoCoreError

def is_retryable(e: Exception) -&gt; bool:
    if isinstance(e, BotoCoreError) and not isinstance(e, ClientError):
        return True  # сетевые
    if isinstance(e, ClientError):
        code = e.response["Error"]["Code"]
        return code in ("Throttling", "ThrottlingException", "RequestLimitExceeded",
                        "InternalError", "ServiceUnavailable", "TooManyRequestsException",
                        "ProvisionedThroughputExceededException", "SlowDown")
    return False

def call_with_backoff(fn, *args, max_attempts=5, base=1.0, **kwargs):
    for attempt in range(max_attempts):
        try:
            return fn(*args, **kwargs)
        except Exception as e:
            if not is_retryable(e) or attempt == max_attempts - 1:
                raise
            delay = base * (2 ** attempt) + random.uniform(0, 1)  # exponential + jitter
            print(f"retry {attempt+1}/{max_attempts} after {delay:.1f}s: {e}")
            time.sleep(delay)
</code></pre>

